<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>location</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="view_location =! view_location">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>

       
         <!-- item registration form starts -->
 <form v-if="view_location" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerLocation">
        <h4 class="text-center">REGISTER LOCATION</h4>
        <div class="row mb-2">
    
            <div class="col-md-12">
                <label class="form-label"> Location Name</label>
                <input type="text" class="form-control" placeholder="Enter Location Name" v-model="name" required>
            </div>

        </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="view_location = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary">Register</button>
        </div>
    </form>
             <!-- item registration form ends-->

              <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="location" :columns="columns" :options="table_option">
                            <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-location-modal'">
                                    <svg
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="2"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="feather feather-edit-3"
                                    >
                                        <path d="M12 20h9"></path>
                                        <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>
                                    </svg>
                                </a>

                                                <a 
                v-if="user_permissions.includes('can_delete_location')"
                href="javascript:void(0);" @click="deleteLocation(props.row)" class="text-danger">
<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-trash" viewBox="0 0 16 16">
  <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
  <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
</svg>
                </a>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        <!-- Edit location modal starts -->
<div class="modal fade mymodal" id="edit-location-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editLocationModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editLocationModalLabel">Edit location</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()"></button>
      </div>
      <form @submit.prevent="updateLocation(view_location_id)">
        <div class="modal-body">
            <div class="row mb-3">
                <div class="col-md-12">
                <label for="name">name</label>
              <input type="text" v-model="name" class="form-control" placeholder="name" required>
            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
<!-- Edit location modal ends -->
      
    </div>
</template>

<style>
    .table3 .actions svg {
        padding: 2px;
    }
</style>

<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Gate Passes' });  
    const showConfirmation = inject('showConfirmation');
    const showMessage = inject('showMessage');
    const view_location = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','name','actions']);    
    const name = ref('');
    const items = ref([]);
    const location = ref([]);
    const view_location_id = ref('');

    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

 

    const getLocation = async () => {
        loading_spinner.value = true;
        try {
            const response = await axiosInstance.get('locations');
            location.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                id: item.id,
                name: item.name,
            }));
        } catch (error) {
            showError(error.message);
        }finally{
            loading_spinner.value = false;
        }
    };
    
    const registerLocation = async () => {
        view_location.value = false;
        loading_spinner.value = true;
        const itemData = {
            name: name.value,
        };
    
        try {
            const response = await axiosInstance.post('/locations', itemData);
            getLocation();
            showMessage('location registered successfully!');
            resetForm();
        } catch (error) {
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };    

    const resetForm = () => {
    name.value = '';
};

    const updateLocation = async (id) => {
        loading_spinner.value = true;
        const payload = {
            name: name.value,
        };
        try {
            const response = await axiosInstance.put(`/locations/${id}`, payload);
          
            getLocation();
            showMessage('location updated successfully!');
            document.getElementById('close_editing').click();
            closeEditModal();
        } catch (error) {
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };

    const openEditModal = (row) => {
        view_location_id.value = row.id;
        name.value = row.name;
    };

    const closeEditModal = () => {
        name.value = '';
    };

    const deleteLocation = async (row) => {
  const res = await showConfirmation(
    'Delete Record',
    'Are you sure you want to delete location. ' + row.name,
    `/approval-lists/${row.id}?deleted=1`,
    'put'
  );
  
  if (res?.refresh) {
    getLocation();
  }
};


    onMounted(() => {
        getLocation();
    });
</script>